import{_ as a,C as n,o as i,c as s,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Weekly 006 — Authority Needs Lineage","description":"","frontmatter":{"title":"Weekly 006 — Authority Needs Lineage","date":"2026-08-23","column":"digital-employee","category":"weekly","article_type":"research-brief","edition":"research-center","research_question":"When agent state survives compaction, resume, delegation, caching, normalization, or reconstruction, what evidence must survive with it so the system can still know what is authorized?","summary":"Twenty-one evidence-validated Daily Research notes show a recurring failure mode: values often survive transformations while their authority does not. Reliable agent runtimes need provenance-preserving admission, where origin, scope, policy context and transformation lineage travel with operational state and are revalidated at the point of use.","sources":["2026-08-17 through 2026-08-23 Daily Runtime V5 publications","research/intelligence/p2-runs/2026/08/2026-08-23-p2-special.json"],"evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"cover":"/assets/covers/weekly-006-authority-needs-lineage-cover-v2.png"},"headers":[],"relativePath":"en/research/weekly/weekly-006.md","filePath":"en/research/weekly/weekly-006.md","lastUpdated":1787666502000}'),l={name:"en/research/weekly/weekly-006.md"};function c(d,e,p,h,u,m){const t=n("ArticleCover");return i(),s("div",null,[o(t,{image:"/assets/covers/weekly-006-authority-needs-lineage-cover-v2.png",kicker:"Weekly Research · 006",title:"Authority Needs Lineage",summary:"State can survive transformation without carrying the authority that once made it valid.",version:"W006",status:"Published 2026-08-23",languageHref:"/zh/research/weekly/weekly-006",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h1 id="weekly-006-—-authority-needs-lineage" tabindex="-1">Weekly 006 — Authority Needs Lineage <a class="header-anchor" href="#weekly-006-—-authority-needs-lineage" aria-label="Permalink to &quot;Weekly 006 — Authority Needs Lineage&quot;">​</a></h1><p>Last week’s synthesis argued that every consequential handoff needs an evidence-bearing receipt. This week’s 21 evidence-validated Daily Research notes expose the next problem: <strong>the state may arrive safely and still become unsafe after it is transformed</strong>.</p><p>Agent runtimes compact transcripts, reconstruct history, resume checkpoints, refresh credentials, merge policies, cache plugins, normalize identifiers, import tool output, inherit environment state, and delegate work. These operations are useful precisely because they preserve continuity. But continuity creates a dangerous illusion: if a value still exists, it can look as though the reason it was once trusted still exists too.</p><p>The week repeatedly shows that this is false.</p><p>A command name can survive while repository configuration changes what the command will execute. A human approval can survive while the approving principal is lost. A child-agent role can survive resume while its effective authority accidentally expands. A refreshed OAuth token can exist in memory while durable persistence failed. A cached absence can survive while the underlying resource was never actually deleted. A recent checkpoint can survive while the policy that grants execution authority has changed. A canonicalized identifier can survive while lifecycle operations are still racing on non-canonical aliases.</p><p>The mechanisms differ, but the control failure is the same:</p><blockquote><p><strong>A surviving value is not a surviving authority claim.</strong></p></blockquote><p>The new weekly judgment is therefore:</p><blockquote><p><strong>Reliable agent systems need provenance-preserving admission. Operational state should carry not only a value, but also the origin, scope, policy context, transformation history and current admission evidence that make the value safe to use. Transformations may preserve or narrow authority; they must not silently strengthen it.</strong></p></blockquote><h2 id="evidence-scope" tabindex="-1">Evidence scope <a class="header-anchor" href="#evidence-scope" aria-label="Permalink to &quot;Evidence scope&quot;">​</a></h2><p>This synthesis uses only Daily Research released from <strong>2026-08-17 through 2026-08-23</strong> after the full V5 publication chain reached a verified terminal state. All seven Daily Runtime records reached <code>publication = Completed</code>, yielding <strong>21 formal Daily Research notes</strong> across Digital Employee, Industry Architecture and Open-source Engineering.</p><table tabindex="0"><thead><tr><th>Date</th><th>Digital Employee</th><th>Industry Architecture</th><th>Open-source Engineering</th></tr></thead><tbody><tr><td>Aug 17</td><td>Selective fail-closed API</td><td>Environment-owned policy</td><td>Compact transcript evidence</td></tr><tr><td>Aug 18</td><td>Accountable human approval</td><td>Persistence and reconciliation</td><td>Trace-to-effect evidence</td></tr><tr><td>Aug 19</td><td>Monotonic delegation authority</td><td>Delivery-context separation</td><td>OAuth refresh split commit</td></tr><tr><td>Aug 20</td><td>Command name is not execution authority</td><td>History is not a transfer contract</td><td>Visible is not durable</td></tr><tr><td>Aug 21</td><td>Useful context is not memory authority</td><td>Approval must name the approver</td><td>Trust the run, not inherited secrets</td></tr><tr><td>Aug 22</td><td>Authorization needs provenance</td><td>Protected constraints, reviewable grants</td><td>Missing cache entry is not deletion evidence</td></tr><tr><td>Aug 23</td><td>Resume recency is not authority</td><td>Creation provenance survives resume</td><td>Canonicalize before lifecycle</td></tr></tbody></table><p>This is an engineering sample, not a claim about universal market practice. The value of the week is the recurrence of one boundary across independently selected mechanisms.</p><p>The P2 lane separately checked the four <code>biweekly-or-release</code> objects due this Sunday. All four reached terminal checks, two monthly objects were not due, and no due object reached the trigger score of 5. No full P2 Special Study ran. One useful governance correction emerged: the <code>agent-style</code> checkpoint stored on Aug 16 lagged a README clarification commit that had already existed before that run, so the current check corrected checkpoint identity without misreporting the old commit as a new weekly change.</p><h2 id="the-recurring-failure-provenance-gets-dropped-during-transformation" tabindex="-1">The recurring failure: provenance gets dropped during transformation <a class="header-anchor" href="#the-recurring-failure-provenance-gets-dropped-during-transformation" aria-label="Permalink to &quot;The recurring failure: provenance gets dropped during transformation&quot;">​</a></h2><p>Last week focused on a boundary between owners. This week shows the same danger inside one owner’s state-processing pipeline.</p><p>A runtime can receive a valid fact and then accidentally detach it from the conditions that gave it meaning.</p><h3 id="a-name-is-not-the-behavior-it-currently-resolves-to" tabindex="-1">A name is not the behavior it currently resolves to <a class="header-anchor" href="#a-name-is-not-the-behavior-it-currently-resolves-to" aria-label="Permalink to &quot;A name is not the behavior it currently resolves to&quot;">​</a></h3><p>The Aug 20 Digital Employee note studied a deceptively simple case: a command can have a familiar, apparently safe name while repository configuration changes the execution that name resolves to.</p><p>That means a policy keyed only by command label is weaker than it appears. The label is an identifier; the actual execution authority depends on the resolved command, configuration source, working context and applicable approval policy.</p><p>The more general form is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stable label</span></span>
<span class="line"><span>+ changed resolution context</span></span>
<span class="line"><span>≠ stable authority</span></span></code></pre></div><p>This pattern reappears in plugin aliases, tool names, model routing labels, saved workflow names and remote session identifiers. A stable key helps correlation, but policy should bind to the effective operation, not merely its familiar name.</p><h3 id="a-human-answer-is-not-a-human-authority-proof" tabindex="-1">A human answer is not a human authority proof <a class="header-anchor" href="#a-human-answer-is-not-a-human-authority-proof" aria-label="Permalink to &quot;A human answer is not a human authority proof&quot;">​</a></h3><p>The Aug 18 and Aug 21 notes converge from different directions.</p><p>One shows why a remote A2A peer must not satisfy a human-confirmation boundary for a dangerous action. The other shows why approval trust must bind to the actual approving principal rather than transport metadata.</p><p>A string such as <code>approved</code>, a callback marked <code>human</code>, or a message delivered through a trusted channel can preserve the response while losing the authority evidence behind it.</p><p>A safer approval record needs to preserve at least:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>occurrence_id</span></span>
<span class="line"><span>approver_principal</span></span>
<span class="line"><span>authority_scope</span></span>
<span class="line"><span>policy_version</span></span>
<span class="line"><span>decision</span></span>
<span class="line"><span>source_provenance</span></span></code></pre></div><p>The principle is not that every approval needs heavy identity infrastructure. It is that the runtime must not silently infer approver authority from message shape or transport path.</p><h3 id="delegation-must-be-monotonic-under-resume-and-customization" tabindex="-1">Delegation must be monotonic under resume and customization <a class="header-anchor" href="#delegation-must-be-monotonic-under-resume-and-customization" aria-label="Permalink to &quot;Delegation must be monotonic under resume and customization&quot;">​</a></h3><p>The Aug 19 Digital Employee note studied child-agent role customization and resume. The key invariant is monotonicity: delegation may narrow or preserve authority, but a representation change should not expand it.</p><p>This is especially important after checkpoint restore. A resumed child agent can reconstruct role labels, tools, context and pending work. If the effective permission envelope is rebuilt from incomplete or stale fields, the resumed representation may become more permissive than the original execution.</p><p>A useful invariant is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authority(after transform) ⊆ Authority(before transform)</span></span></code></pre></div><p>unless a fresh, explicit grant is admitted.</p><p>That single rule connects role customization, policy merging, saved approvals, connector capability reconstruction and remote-session resume.</p><h2 id="continuity-mechanisms-need-an-admission-boundary" tabindex="-1">Continuity mechanisms need an admission boundary <a class="header-anchor" href="#continuity-mechanisms-need-an-admission-boundary" aria-label="Permalink to &quot;Continuity mechanisms need an admission boundary&quot;">​</a></h2><p>A recurring engineering mistake is to treat persistence as the final correctness property.</p><p>This week’s evidence says persistence solves only one question: <strong>did the value survive?</strong> It does not answer <strong>should the value still be used?</strong></p><h3 id="refresh-success-is-not-durable-credential-state" tabindex="-1">Refresh success is not durable credential state <a class="header-anchor" href="#refresh-success-is-not-durable-credential-state" aria-label="Permalink to &quot;Refresh success is not durable credential state&quot;">​</a></h3><p>The Aug 19 engineering note examined OAuth refresh as a split commit.</p><p>A provider can issue refreshed credentials successfully while local durable persistence fails. At that moment, memory contains a valid new token but the durable store still contains the old state. If the failure is hidden, later workers can resume from a credential state that never matched the successful refresh event.</p><p>The correct boundary is explicit:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider refresh accepted</span></span>
<span class="line"><span>≠ credential state durably committed</span></span></code></pre></div><p>A fail-visible design records the split rather than pretending the refresh transaction was atomic.</p><p>This pattern generalizes to approval persistence, checkpoint writes, session rebinding, artifact publication and tool-result caching.</p><h3 id="visible-is-not-durable" tabindex="-1">Visible is not durable <a class="header-anchor" href="#visible-is-not-durable" aria-label="Permalink to &quot;Visible is not durable&quot;">​</a></h3><p>The Aug 20 engineering note reaches the same point through artifact publication. Pending-state isolation followed by an atomic rename prevents consumers from observing a partially published version as though it were authoritative.</p><p>The important insight is broader than filesystem rename:</p><blockquote><p><strong>Visibility is a weaker fact than durable admission.</strong></p></blockquote><p>A value may be readable while still provisional. A UI may display a task while its authoritative record is not committed. A remote object may be discoverable while reconciliation has not confirmed ownership. A model output may be available while it has not crossed an evidence gate.</p><p>Systems benefit from explicit states such as <code>pending</code>, <code>admitted</code>, <code>committed</code>, <code>verified</code>, and <code>superseded</code> rather than one overloaded “exists” flag.</p><h3 id="recency-is-not-authority" tabindex="-1">Recency is not authority <a class="header-anchor" href="#recency-is-not-authority" aria-label="Permalink to &quot;Recency is not authority&quot;">​</a></h3><p>The Aug 23 Digital Employee note sharpens this problem for resume.</p><p>A recent checkpoint can be operationally useful because it reduces reconstruction work. But “latest” is an ordering fact, not a permission fact. The newest snapshot can still contain stale grants, revoked assumptions, old principal bindings, or state created under an obsolete policy epoch.</p><p>Therefore resume should ask two separate questions:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which state is newest?</span></span>
<span class="line"><span>Which state is currently admissible?</span></span></code></pre></div><p>A runtime that answers only the first is fast but not governed.</p><h2 id="information-can-be-useful-without-being-authorized-state" tabindex="-1">Information can be useful without being authorized state <a class="header-anchor" href="#information-can-be-useful-without-being-authorized-state" aria-label="Permalink to &quot;Information can be useful without being authorized state&quot;">​</a></h2><p>Several notes this week separate informational usefulness from operational authority.</p><h3 id="external-tool-output-is-not-reusable-memory-by-default" tabindex="-1">External tool output is not reusable memory by default <a class="header-anchor" href="#external-tool-output-is-not-reusable-memory-by-default" aria-label="Permalink to &quot;External tool output is not reusable memory by default&quot;">​</a></h3><p>The Aug 21 Digital Employee note distinguishes standalone external tool output from reusable agent memory.</p><p>Tool output can be valuable context. But promoting it into memory changes its lifecycle: it may be replayed later, surfaced to different tasks, or treated as durable background truth.</p><p>That promotion should therefore be an admission operation with provenance, scope and expiry—not an automatic consequence of the tool returning a value.</p><p>A useful context item can remain useful without becoming long-lived authority.</p><h3 id="history-is-not-a-transfer-contract" tabindex="-1">History is not a transfer contract <a class="header-anchor" href="#history-is-not-a-transfer-contract" aria-label="Permalink to &quot;History is not a transfer contract&quot;">​</a></h3><p>The Aug 20 Industry Architecture note studies history reconstruction across agents. Replaying prior interaction history can restore context, but credential-bearing control calls should be scrubbed rather than transferred as ordinary conversational state.</p><p>This is a crucial distinction:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>replayable history</span></span>
<span class="line"><span>≠ transferable capability</span></span></code></pre></div><p>The fact that a prior worker used a token, connector grant, approval or control instruction does not make that capability part of the receiving worker’s transferable context.</p><p>The same principle applies to shell environment variables, API secrets, temporary approval tokens and provider session cookies.</p><h3 id="delivery-and-model-context-are-different-stores" tabindex="-1">Delivery and model context are different stores <a class="header-anchor" href="#delivery-and-model-context-are-different-stores" aria-label="Permalink to &quot;Delivery and model context are different stores&quot;">​</a></h3><p>The Aug 19 Industry Architecture note separates asynchronous user delivery from model input context while retaining replayable delivery metadata.</p><p>This is another provenance boundary. A message can be important for delivery audit without belonging in future model context. Conversely, model context may contain reasoning state that should never be exposed as user-delivery history.</p><p>Separating these stores reduces accidental authority propagation because “was delivered” no longer implies “should condition future execution.”</p><h2 id="absence-cache-state-and-canonical-identity-need-stronger-semantics" tabindex="-1">Absence, cache state and canonical identity need stronger semantics <a class="header-anchor" href="#absence-cache-state-and-canonical-identity-need-stronger-semantics" aria-label="Permalink to &quot;Absence, cache state and canonical identity need stronger semantics&quot;">​</a></h2><p>Not all dangerous transformations add data. Some remove or normalize it.</p><h3 id="missing-is-not-deleted" tabindex="-1">Missing is not deleted <a class="header-anchor" href="#missing-is-not-deleted" aria-label="Permalink to &quot;Missing is not deleted&quot;">​</a></h3><p>The Aug 22 engineering note examines plugin-cache reconciliation with account scoping, serialization and generation guards.</p><p>The key negative fact is simple: a missing cache entry does not prove the underlying plugin was deleted. The cache may be stale, incomplete, generated from another account, or overwritten by an older reconciliation generation.</p><p>This is the negative-evidence form of the week’s thesis:</p><blockquote><p><strong>Absence without provenance is not authoritative absence.</strong></p></blockquote><p>Deletion, revocation and non-existence are consequential claims. They often need an authoritative source read, tombstone, generation number or reconciled snapshot rather than inference from a local miss.</p><h3 id="canonicalize-before-lifecycle-operations" tabindex="-1">Canonicalize before lifecycle operations <a class="header-anchor" href="#canonicalize-before-lifecycle-operations" aria-label="Permalink to &quot;Canonicalize before lifecycle operations&quot;">​</a></h3><p>The Aug 23 engineering note shows why logically equivalent identifiers should be canonicalized before lifecycle operations race on them.</p><p>Without canonicalization, two aliases can create two apparent ownership paths for one underlying resource. Locks, cleanup, restart, cache keys and deduplication can then operate on representation rather than identity.</p><p>Canonicalization is therefore not cosmetic normalization. It is an admission step that decides which identity participates in the lifecycle.</p><p>But canonicalization alone is not enough: the canonical identity still needs provenance, scope and current policy.</p><h2 id="a-reusable-model-provenance-preserving-admission" tabindex="-1">A reusable model: Provenance-Preserving Admission <a class="header-anchor" href="#a-reusable-model-provenance-preserving-admission" aria-label="Permalink to &quot;A reusable model: Provenance-Preserving Admission&quot;">​</a></h2><p>The week supports a compact control model.</p><p>Every operational fact can be represented as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OperationalFact = {</span></span>
<span class="line"><span>  value,</span></span>
<span class="line"><span>  origin,</span></span>
<span class="line"><span>  principal,</span></span>
<span class="line"><span>  scope,</span></span>
<span class="line"><span>  policy_epoch,</span></span>
<span class="line"><span>  occurrence_id,</span></span>
<span class="line"><span>  transform_lineage,</span></span>
<span class="line"><span>  durability_state,</span></span>
<span class="line"><span>  verification_state</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Not every system needs every field literally. The point is semantic: the runtime should know not just <em>what</em> the current value is, but <em>why it is allowed to mean what the next component thinks it means</em>.</p><p>A transformation then has a governed shape:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input fact</span></span>
<span class="line"><span>→ transform</span></span>
<span class="line"><span>→ preserve provenance</span></span>
<span class="line"><span>→ narrow or preserve scope</span></span>
<span class="line"><span>→ revalidate policy-sensitive fields</span></span>
<span class="line"><span>→ admit output fact</span></span></code></pre></div><p>The dangerous alternative is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input value</span></span>
<span class="line"><span>→ transform</span></span>
<span class="line"><span>→ output value</span></span>
<span class="line"><span>→ assume old authority still applies</span></span></code></pre></div><p>This model gives a practical interpretation to several mechanisms from the week:</p><ul><li>selective fail-closed parsing protects against silent policy-field loss;</li><li>environment-owned variable policy preserves where execution context came from;</li><li>compact transcript presentation preserves full evidence behind the compact view;</li><li>named approver identity preserves who granted authority;</li><li>monotonic delegation prevents transformation from expanding scope;</li><li>split-commit visibility preserves the difference between issued and persisted credentials;</li><li>atomic publication preserves the difference between visible and admitted artifacts;</li><li>memory admission preserves the difference between useful context and durable background state;</li><li>generation-guarded cache reconciliation preserves snapshot provenance;</li><li>resume re-admission preserves the difference between newest state and currently valid state;</li><li>canonicalization preserves one lifecycle identity before concurrency begins.</li></ul><h2 id="what-changed-relative-to-last-week" tabindex="-1">What changed relative to last week <a class="header-anchor" href="#what-changed-relative-to-last-week" aria-label="Permalink to &quot;What changed relative to last week&quot;">​</a></h2><p>Weekly 005 proposed evidence-bearing handoff receipts at ownership boundaries. Weekly 006 does not replace that model; it moves the same requirement inside the state machine.</p><p>A handoff receipt answers:</p><blockquote><p>What fact and authority crossed from one owner to another?</p></blockquote><p>Provenance-preserving admission answers:</p><blockquote><p>After the receiver transformed, cached, compacted, resumed or reconstructed that fact, what authority is still valid now?</p></blockquote><p>Together they imply a stronger invariant:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authority must be traceable across both transfer and transformation.</span></span></code></pre></div><p>A system can have excellent inter-service receipts and still fail if local resume code drops policy epoch. It can have perfect checkpoint lineage and still fail if a remote handoff does not identify the approving principal. Reliable long-running agents need both.</p><h2 id="tensions-this-model-does-not-eliminate" tabindex="-1">Tensions this model does not eliminate <a class="header-anchor" href="#tensions-this-model-does-not-eliminate" aria-label="Permalink to &quot;Tensions this model does not eliminate&quot;">​</a></h2><h3 id="full-lineage-versus-operational-cost" tabindex="-1">Full lineage versus operational cost <a class="header-anchor" href="#full-lineage-versus-operational-cost" aria-label="Permalink to &quot;Full lineage versus operational cost&quot;">​</a></h3><p>Recording every transformation can become expensive and unreadable. The goal should not be universal event sourcing by default.</p><p>Systems need a risk-based rule: preserve strong lineage for facts that affect execution authority, external side effects, durable memory, credentials, identity and policy; use lighter telemetry for ordinary informational transformations.</p><h3 id="revalidation-versus-availability" tabindex="-1">Revalidation versus availability <a class="header-anchor" href="#revalidation-versus-availability" aria-label="Permalink to &quot;Revalidation versus availability&quot;">​</a></h3><p>Fresh authorization checks can fail during network partitions or provider outages. Fail-closed behavior is appropriate for consequential authority, but not every read-only operation needs the same standard.</p><p>The challenge is to declare which facts require fresh admission and which may safely use bounded cached evidence.</p><h3 id="canonical-identity-versus-evolving-systems" tabindex="-1">Canonical identity versus evolving systems <a class="header-anchor" href="#canonical-identity-versus-evolving-systems" aria-label="Permalink to &quot;Canonical identity versus evolving systems&quot;">​</a></h3><p>Canonicalization assumes a stable mapping. Real systems rename resources, migrate accounts and merge identities.</p><p>The canonical identity therefore needs versioned mapping evidence rather than an eternal string.</p><h3 id="monotonic-authority-versus-legitimate-escalation" tabindex="-1">Monotonic authority versus legitimate escalation <a class="header-anchor" href="#monotonic-authority-versus-legitimate-escalation" aria-label="Permalink to &quot;Monotonic authority versus legitimate escalation&quot;">​</a></h3><p>Sometimes authority really must expand: a human grants an exception, an administrator unlocks a tool, or a workflow enters a privileged phase.</p><p>The rule is not “authority can never increase.” It is “authority cannot increase merely because representation changed.” Expansion needs a new explicit grant with its own provenance.</p><h2 id="predictions" tabindex="-1">Predictions <a class="header-anchor" href="#predictions" aria-label="Permalink to &quot;Predictions&quot;">​</a></h2><p>These are Research Center interpretations from the recurring evidence, not claims made by any single Daily source.</p><ol><li><strong>Resume protocols will increasingly expose policy epochs.</strong> A checkpoint ID alone will be insufficient for governed recovery.</li><li><strong>Approval records will become principal-bound artifacts.</strong> Systems will distinguish the text of a decision from evidence of who was allowed to make it.</li><li><strong>Agent memory will gain explicit admission metadata.</strong> Tool output and delivery history will no longer be promoted automatically into durable memory in higher-assurance runtimes.</li><li><strong>Credential refresh APIs will expose split-commit states.</strong> “Refreshed but not persisted” will become a first-class recoverable condition.</li><li><strong>Caches will carry generation and authority provenance.</strong> A cache miss will be treated as uncertainty unless the cache is known to be an authoritative complete snapshot.</li><li><strong>Canonical identity will move earlier in lifecycle control.</strong> Locking, deduplication and ownership will increasingly operate on canonical resource identity rather than user-facing aliases.</li><li><strong>Compact audit views will retain links to full evidence.</strong> Human-readable summaries will not be accepted as substitutes for replayable underlying traces.</li></ol><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>What is the minimal provenance envelope worth standardizing across agents, tools and connectors?</li><li>Which policy changes should invalidate previously admitted state during resume?</li><li>How should a runtime prove that authority narrowed monotonically through a sequence of transforms?</li><li>When is a local cache complete enough that absence can become authoritative negative evidence?</li><li>How long should approval provenance remain reusable, and what revokes it?</li><li>Can canonical identity remain stable across account migration, provider rebinding and resource rename?</li><li>Which state transformations deserve durable lineage and which are safe to keep as transient telemetry?</li><li>How should a runtime represent “valid value, invalid authority” without throwing away useful context?</li></ul><h2 id="next-week-research-priorities" tabindex="-1">Next-week research priorities <a class="header-anchor" href="#next-week-research-priorities" aria-label="Permalink to &quot;Next-week research priorities&quot;">​</a></h2><p>Three concrete tests would sharpen this model.</p><p><strong>First, test resume under policy change.</strong> Create a checkpoint under policy epoch A, revoke or narrow the relevant authority, then resume under epoch B. The acceptance criterion is that useful state survives while obsolete authority does not.</p><p><strong>Second, test provenance through compaction.</strong> Compact an execution transcript and require the compact representation to retain resolvable evidence for every authority-sensitive claim. The test should fail if the summary becomes the only surviving evidence.</p><p><strong>Third, test authoritative negative evidence.</strong> Remove a resource from a local cache without deleting it at the source of truth. The runtime should report uncertainty or stale cache state, not authoritative deletion.</p><p>The direction is now clearer than a generic call for “more audit logs.” Long-running agent systems need <strong>typed trust continuity</strong>.</p><p>A value can be current but unauthorized. A message can be human-shaped but not human-authorized. A token can be valid but not durably committed. A cache can be empty but not authoritative. A checkpoint can be recent but inadmissible. An identifier can be stable but non-canonical.</p><p><strong>Authority needs lineage because persistence preserves data more easily than it preserves the reasons that made the data safe to act on.</strong></p>`,135))])}const y=a(l,[["render",c]]);export{v as __pageData,y as default};
